"use client";

import { useQuery } from "@tanstack/react-query";
import { useEffect, type ReactNode } from "react";

import { LocaleText } from "@/components/ops/locale-text";
import { Money } from "@/components/ops/money";
import { EmptyState, ErrorState, LoadingState } from "@/components/ops/states";
import { useStaffSession } from "@/components/ops/staff-session";
import { browserApi } from "@/lib/api/browser";
import { roleLabel } from "@/lib/auth/roles";
import { denyAccess } from "@/lib/auth/session-client";
import { fill } from "@/lib/i18n/dictionary";
import { commonCopy } from "@/lib/i18n/staff/common";
import { navCopy } from "@/lib/i18n/staff/nav";
import { useStaffSection } from "@/lib/i18n/staff/use-copy";
import { getNavItem } from "@/lib/nav";
import { useScope } from "@/stores/scope";

export function RoleGate({
  href,
  children,
}: {
  href: string;
  children: ReactNode;
}) {
  const t = useStaffSection(commonCopy);
  const me = useStaffSession();
  const item = getNavItem(href);
  const allowed = Boolean(me && item && item.roles.includes(me.role));
  useEffect(() => {
    if (me && item && !allowed) denyAccess();
  }, [me, item, allowed]);
  if (!me || !item) return null;
  if (!allowed) return <LoadingState label={t.takingYou} />;
  return children;
}

export function Screen({ href }: { href: string }) {
  const t = useStaffSection(commonCopy);
  const nav = useStaffSection(navCopy);
  const me = useStaffSession();
  const item = getNavItem(href);
  const brandId = useScope((state) => state.brandId);
  const branchId = useScope((state) => state.branchId);
  const branch = useQuery({
    queryKey: ["branch", branchId, brandId],
    enabled: Boolean(branchId),
    retry: false,
    queryFn: async () => {
      const { data, error, response } = await browserApi.GET("/api/v1/branches/{branch_id}", {
        params: { path: { branch_id: branchId ?? "" } },
      });
      if (!response.ok) {
        const detail =
          error && typeof error === "object" && "detail" in error
            ? String(error.detail)
            : fill(t.branchFailed, { status: response.status });
        throw new Error(detail);
      }
      return data;
    },
  });

  if (!item || !me) return null;

  return (
    <RoleGate href={href}>
      <div className="mx-auto grid max-w-3xl gap-4">
        <header>
          <p className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
            {nav.groups[item.group]}
          </p>
          <h1 className="text-[length:var(--text-28)] font-semibold">{nav[item.labelKey]}</h1>
          <p className="mt-1 text-sm text-muted-foreground">
            {fill(t.signedInAs, { name: me.full_name, role: roleLabel(me.role) })}
          </p>
        </header>
        <section className="rounded-xl border bg-card p-4 shadow-elev-1">
          <h2 className="text-sm font-medium">{t.workingLocation}</h2>
          {!branchId ? (
            <p className="mt-2 text-sm text-muted-foreground">{t.openBranch}</p>
          ) : branch.isLoading ? (
            <div className="mt-3">
              <LoadingState label={t.loadingBranch} />
            </div>
          ) : branch.isError ? (
            <div className="mt-3">
              <ErrorState
                title={t.branchUnavailable}
                body={branch.error instanceof Error ? branch.error.message : t.retryBranch}
                onRetry={() => void branch.refetch()}
              />
            </div>
          ) : (
            <dl className="mt-3 grid gap-2 text-sm">
              <div>
                <dt className="text-muted-foreground">{t.branch}</dt>
                <dd className="font-medium">
                  <LocaleText value={branch.data?.name} />
                </dd>
              </div>
              <div>
                <dt className="text-muted-foreground">{t.sampleAmount}</dt>
                <dd>
                  <Money amount="0.00" currency={branch.data?.currency || "EGP"} />
                </dd>
              </div>
              <div>
                <dt className="text-muted-foreground">{t.nextHeaders}</dt>
                <dd className="font-mono text-xs break-all">
                  X-Brand-ID {brandId ?? "—"}
                  <br />
                  X-Branch-ID {branchId}
                </dd>
              </div>
            </dl>
          )}
        </section>
        <EmptyState
          title={fill(t.phaseReady, { label: nav[item.labelKey], phase: item.phase })}
          body={t.phaseBody}
        />
      </div>
    </RoleGate>
  );
}
